// === Safe JSON parser ===
function safeJsonParse(str) {
  if (!str || typeof str !== 'string' || str.trim() === '') {
    return {};
  }
  try {
    return JSON.parse(str);
  } catch {
    const messageMatch = str.match(/"message"\s*:\s*"([^"]+)"/);
    if (messageMatch) return { message: messageMatch[1] };
    return {};
  }
}

// === Extract user message ===
function extractMessage(input) {
  let text = '';
  try {
    if (input.message) {
      text = input.message;
    } else if (input.body && typeof input.body === 'object') {
      text = input.body.message || input.body.chatInput || '';
    } else if (input.body && typeof input.body === 'string') {
      const parsed = safeJsonParse(input.body);
      text = parsed.message || parsed.chatInput || input.body;
    } else if (input.query && input.query.message) {
      text = input.query.message;
    } else {
      const stringValues = Object.values(input).filter(v =>
        typeof v === 'string' &&
        v.trim().length > 0 &&
        !v.startsWith('http') &&
        !v.startsWith('Mozilla')
      );
      if (stringValues.length > 0) text = stringValues[0];
    }
  } catch {
    text = '';
  }
  return String(text || '').trim();
}

// === Normalize Axi-Technologies consistently ===
function normalizeAxi(text) {
  return text.replace(/\(?\s*axi[\s-]*technologies\s*\)?/gi, 'Axi-Technologies');
}

// === Process all incoming items ===
return items.map(item => {
  const input = item.json || {};
  let text = normalizeAxi(extractMessage(input));
  if (!text) text = 'Hello';

  // Language detection
  const containsArabic = /[\u0600-\u06FF]/.test(text);
  const englishWords = [
    'what','where','who','how','when','why','is','are','the','a','in',
    'on','of','to','with','and','for','you','your','hello','hi','help'
  ];
  const words = text.toLowerCase().match(/[a-zA-Z]+/g) || [];
  const englishCount = words.filter(w => englishWords.includes(w)).length;
  const englishRatio = words.length ? englishCount / words.length : 0;

  let replyLanguage;
  if (containsArabic) {
    replyLanguage = 'urdu';
  } else if (words.length === 0) {
    replyLanguage = 'english';
  } else {
    replyLanguage = englishRatio > 0.4 ? 'english' : 'roman_urdu';
  }

  return {
    json: {
      replyLanguage,
      userText: text,
      name:$('Webhook').first().json.body.name,
      email:$('Webhook').first().json.body.email,
      phone:$('Webhook').first().json.body.contact,
      message: $('Webhook').first().json.body.message
      // debug info can be added here if needed
      // debug: { containsArabic, englishRatio, englishCount, words }
    }
  };
});

// === WordPress Chatbot Formatter ===

// --- Simple Axi protection ---
function protectAxiOnce(text) {
  return text.replace(/\baxi[\s-]*technologies?\b/gi, '__AXI__');
}

function restoreAxi(text) {
  return text.replace(/__AXI__/g, 'Axi-Technologies');
}

// --- Protect & Restore Markdown links ---
function protectMarkdownLinks(text) {
  const links = [];
  const protectedText = text.replace(/\[[^\]]+\]\([^)]+\)/g, (m) => {
    links.push(m);
    return `__MDLINK_${links.length - 1}__`;
  });
  return { protectedText, links };
}

function restoreMarkdownLinks(text, links) {
  return text.replace(/__MDLINK_(\d+)__/g, (_, i) => links[+i]);
}

// --- Linkify plain emails/URLs ---
function linkify(text) {
  const { protectedText, links } = protectMarkdownLinks(text);
  let t = protectedText;

  t = t.replace(/\b([A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,})\b/g,
    '[$1](mailto:$1)'
  );

  t = t.replace(/\b((https?:\/\/|www\.)[^\s)<]+)\b/g, (m, url) => {
    const u = url.startsWith('http') ? url : `https://${url}`;
    return `[${url}](${u})`;
  });

  return restoreMarkdownLinks(t, links);
}

// --- Robust English term processor for Urdu ---
function processEnglishTermsForUrdu(text) {
  const protectedBlocks = [];

  text = text.replace(/\[[^\]]+\]\([^)]+\)/g, (m) => {
    protectedBlocks.push(m);
    return `__PROTECTED_${protectedBlocks.length - 1}__`;
  });

  text = text.replace(/(https?:\/\/[^\s)<]+|www\.[^\s)<]+)/g, (m) => {
    protectedBlocks.push(m);
    return `__PROTECTED_${protectedBlocks.length - 1}__`;
  });

  text = text.replace(/\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g, (m) => {
    protectedBlocks.push(m);
    return `__PROTECTED_${protectedBlocks.length - 1}__`;
  });

  text = protectAxiOnce(text);

  const lineBreakToken = '__LINE_BREAK__';
  text = text.replace(/\n/g, lineBreakToken);

  text = text.replace(/\(([A-Za-z][A-Za-z0-9\s\-\/#&+.]*[A-Za-z0-9])\)/g, (match) => match);

  text = text.replace(/\b([A-Z][A-Za-z0-9]{1,}(?:\s+[A-Z][A-Za-z0-9]*)*)\b/g, (match) => match);

  text = text.replace(new RegExp(lineBreakToken, 'g'), '\n');

  text = text.replace(/__PROTECTED_(\d+)__/g, (_, i) => protectedBlocks[+i]);

  return text;
}

// ✅ NEW HTML RTL WRAPPER
function wrapCompleteTextRTL(text) {
  return `<div dir="rtl" style="text-align:right;">${text}</div>`;
}

// ✅ Force AXI to display LTR but stay on RIGHT
function isolateAXI(text) {
  return text.replace(
    /Axi-Technologies/g,
    `<span dir="ltr" style="display:inline-block;">Axi-Technologies</span>`
  );
}

// --- CTA Labels ---
const LABELS = {
  booking: {
    english: 'Book a meeting',
    urdu: 'میٹنگ بک کریں',
    roman_urdu: 'Meeting book karein'
  },
  cost: {
    english: 'Cost Calculator',
    urdu: 'لاگت کیلکولیٹر',
    roman_urdu: 'Cost Calculator'
  }
};

// === FINAL ROBUST Main processing ===
return items.map(item => {
  const j = item.json || {};
  let out = (j.output || j.message || '').toString().trim();

  out = protectAxiOnce(out);

  out = linkify(out);

  let lang = (j.replyLanguage || '').toLowerCase();

  const bookingLabel = LABELS.booking[lang] || LABELS.booking.english;
  const costLabel = LABELS.cost[lang] || LABELS.cost.english;

  out = out.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (m, label, url) => {
    const u = url.trim();
    if (/cal\.com\/axi-technologies\//i.test(u)) return `[${bookingLabel}](${u})`;
    if (/costcalculator\.axitechnologies\.ai/i.test(u)) return `[${costLabel}](${u})`;
    return m;
  });

  const linkMatches = [...out.matchAll(/\[([^\]]+)\]\(([^)]+)\)/g)];
  const links = linkMatches.map(m => ({
    label: m[1].trim(),
    href: m[2].trim()
  }));

  let htmlReply = out.replace(/\[([^\]]+)\]\(([^)]+)\)/g,
    (m, label, url) => `<a href="${url}" target="_blank" rel="noopener noreferrer">${label}</a>`
  );

  if (lang === 'roman_urdu') {
    htmlReply = htmlReply.replace(/[\u0600-\u06FF]/g, '').replace(/ {2,}/g, ' ').trim();
  }

  if (lang === 'urdu') {
    htmlReply = processEnglishTermsForUrdu(htmlReply);

    // ✅ FULL RTL ENFORCEMENT (HTML-based)
    htmlReply = wrapCompleteTextRTL(htmlReply);
  }

  // ✅ Restore Axi
  htmlReply = restoreAxi(htmlReply);

  // ✅ Force AXI readable + placed on RIGHT
  htmlReply = isolateAXI(htmlReply);

  htmlReply = htmlReply
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  return {
    json: {
      name: $input.first().json.name,
      email: $input.first().json.email,
      phone: $input.first().json.phone,
      success: true,
      reply: htmlReply,
      replyLanguage: lang,
      cleaned: htmlReply,
      links
    }
  };
});
